window.MG_LAZY_DATA["data/lazy/courses/a025-226ba3d159974ca3.json"]={sha256:"226ba3d159974ca37b80cb8844cb38dd5cd672723c0e50d2d280322d51167f73",value:{"id":"a025","title":"背面供電網路製程","titleEn":"Backside power-delivery processing","category":"semiconductor","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"stepCount":24,"estimatedMinutes":720,"languageCoverage":["zh-TW","en"],"sourceIds":["v7-bspdn-dtco","v7-bspdn-demo","v7-bspdn-flow","v7-bspdn-building","v7-bspdn-esd","v7-bspdn-intel","v10-video-bf0998107592"],"simulationOnly":true,"summary":"拆解前後側供電分工、鍵合與薄化、奈米通孔連接，再以壓降、熱與可靠度證據審查整合方案。","summaryEn":"Separate signal and power routing, plan bonding, thinning and backside contacts, then review the integration using voltage-drop, thermal and reliability evidence.","scope":"依公開原理編寫的四階段、24 個教學工作包；每步需交出模型、判讀或驗證紀錄。數值練習為自訂教學案例，不是廠商製程配方、現場操作許可或專業設計認證。","scopeEn":"Four stages and 24 educational work packages based on public principles. Each step produces a model, interpretation or verification record. Numerical exercises are hypothetical, not manufacturer recipes, field operating authorization or professional design certification.","diagram":{"type":"wafer","labels":["訊號層","元件","背面接觸","電源網路","封裝"],"labelsEn":["Signal layers","Devices","Backside contacts","Power network","Package"],"original":true,"notToScale":true},"stages":[{"id":"a025-stage01","order":1,"title":"系統需求與電源路徑","titleEn":"Requirements and power paths","description":"先建立電源與訊號、電阻與暫態的不同證據。","descriptionEn":"Separate power from signals and resistive from transient evidence.","steps":[{"id":"a025-v7-01","order":1,"sequence":1,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-dtco"],"prerequisiteIds":[],"title":"畫出電源與訊號的兩條路徑","titleEn":"Draw separate power and signal paths","objective":"區分供電網路與訊號傳播。","objectiveEn":"Distinguish power distribution from signal propagation.","instruction":"先畫封裝、正面金屬及電晶體；用另一色畫背面電源進入點；追蹤 VDD 與 VSS 完整回路；圈出仍留在正面的訊號。","instructionEn":"Sketch the package, frontside metals and transistor; add backside power entry in another color; trace the complete VDD and VSS loop; circle signals remaining on the front.","observation":"供電轉到背面後，訊號層並未消失。","observationEn":"Moving power does not eliminate signal layers.","failure":"若只畫 VDD，補回回流路徑後再分析壓降。","failureEn":"If only VDD is drawn, add the return path before analyzing drop.","check":"交出含兩種網路與回流的截面。","checkEn":"Submit a section with both networks and the return path.","knowledge":[{"id":"a025-v7-01-k1","title":"原理與限制","titleEn":"Principle and limits","text":"背面供電改變配線分工，不代表把所有訊號移到背面。","textEn":"Backside power changes routing allocation; it does not move every signal backside."},{"id":"a025-v7-01-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"電壓是兩點之差，供電與回流都影響元件實際供應。","textEn":"Voltage is a difference between points; both supply and return affect the device."}],"quiz":{"question":"背面供電截面應保留什麼？","questionEn":"What should a backside-power section retain?","options":["正面訊號及完整供電回路。","只有單一 VDD 箭頭。","完全刪除正面互連。"],"optionsEn":["Frontside signals and the complete power loop.","Only one VDD arrow.","All frontside interconnect removed."],"answer":0,"explanation":"正面訊號及完整供電回路。 背面供電改變配線分工，不代表把所有訊號移到背面。","explanationEn":"Frontside signals and the complete power loop. Backside power changes routing allocation; it does not move every signal backside."}},{"id":"a025-v7-02","order":2,"sequence":2,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-dtco"],"prerequisiteIds":["a025-v7-01"],"title":"比較三種電源軌配置","titleEn":"Compare three rail configurations","objective":"把幾何改善與供電改善分開。","objectiveEn":"Separate geometry gains from delivery gains.","instruction":"畫傳統正面、正面連接埋藏軌、背面連接埋藏軌三圖；逐圖標出接觸點；比較訊號可用空間；列出每種新增介面。","instructionEn":"Draw conventional frontside, frontside-connected buried rails and backside-connected buried rails; mark contacts; compare signal space; list added interfaces.","observation":"埋藏軌與背面供電不是完全同義。","observationEn":"Buried rails and backside delivery are not synonymous.","failure":"若三圖只換顏色，重新追蹤封裝到元件的連通性。","failureEn":"If only colors differ, retrace connectivity from package to device.","check":"表格能分辨軌位置與供電進入側。","checkEn":"The table distinguishes rail position from power-entry side.","knowledge":[{"id":"a025-v7-02-k1","title":"原理與限制","titleEn":"Principle and limits","text":"電源軌位置和電源進入側是兩個設計選項。","textEn":"Rail location and power-entry side are separate choices."},{"id":"a025-v7-02-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"介面增加可能帶來新的對準與可靠度要求。","textEn":"Additional interfaces can create alignment and reliability requirements."}],"quiz":{"question":"有埋藏電源軌就一定由背面供電嗎？","questionEn":"Do buried rails necessarily imply backside delivery?","options":["一定，兩者是同一名詞。","不一定，須追蹤電源連接。","只要有埋藏軌便沒有接觸電阻。"],"optionsEn":["Yes; the terms are identical.","No; trace the power connection.","Buried rails eliminate contact resistance."],"answer":1,"explanation":"不一定，須追蹤電源連接。 電源軌位置和電源進入側是兩個設計選項。","explanationEn":"No; trace the power connection. Rail location and power-entry side are separate choices."}},{"id":"a025-v7-03","order":3,"sequence":3,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-dtco"],"prerequisiteIds":["a025-v7-02"],"title":"建立直流壓降帳本","titleEn":"Build a DC voltage-drop ledger","objective":"用簡化電阻網路定位主要損耗。","objectiveEn":"Locate losses with a simplified resistive network.","instruction":"自行設定三段串聯電阻與電流並註明是假設；分別計算 I×R；把各段壓降相加；比較加寬其中一段前後結果。","instructionEn":"Choose hypothetical current and three series resistances; calculate each I×R drop; sum the drops; compare widening one segment.","observation":"改善最小電阻段不一定改善整體瓶頸。","observationEn":"Improving the smallest resistance may barely change the bottleneck.","failure":"勿把示例電阻當成某節點的實測值；補上假設標籤。","failureEn":"Do not present example resistances as measurements of a named node.","check":"每段單位、總壓降及最大貢獻可追溯。","checkEn":"Units, total drop and largest contributor are traceable.","knowledge":[{"id":"a025-v7-03-k1","title":"原理與限制","titleEn":"Principle and limits","text":"串聯路徑的電阻貢獻需逐段相加。","textEn":"Series-path resistance contributions add."},{"id":"a025-v7-03-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"R 的變化與 I 的變化都會改變壓降，不能只比較線寬。","textEn":"Both resistance and current change drop; width alone is insufficient."}],"quiz":{"question":"哪一段先值得改善？","questionEn":"Which segment warrants attention first?","options":["顏色最深的段。","永遠是最靠近封裝的一段。","在同一電流條件下壓降最大的段。"],"optionsEn":["The darkest-colored segment.","Always the segment nearest the package.","The largest-drop segment at the same current."],"answer":2,"explanation":"在同一電流條件下壓降最大的段。 串聯路徑的電阻貢獻需逐段相加。","explanationEn":"The largest-drop segment at the same current. Series-path resistance contributions add."}},{"id":"a025-v7-04","order":4,"sequence":4,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-demo"],"prerequisiteIds":["a025-v7-03"],"title":"分開靜態壓降與瞬態下陷","titleEn":"Separate static drop from transient droop","objective":"辨識負載突變造成的時間效應。","objectiveEn":"Identify time-dependent effects of load changes.","instruction":"畫穩定負載與階躍負載兩條曲線；標出電流變化時刻；把穩態壓降與短暫谷值分別量測；比較兩種去耦配置的假設波形。","instructionEn":"Draw steady and stepped loads; mark the current transition; measure steady drop separately from the temporary minimum; compare two hypothetical decoupling waveforms.","observation":"相同直流電阻仍可能有不同瞬態谷值。","observationEn":"Equal DC resistance can coexist with different transient minima.","failure":"只用平均電壓會漏掉谷值；保留時間尺度。","failureEn":"Average voltage can conceal minima; retain the time scale.","check":"報告同時列出穩態值、最小值及恢復時間。","checkEn":"Report steady value, minimum and recovery time.","knowledge":[{"id":"a025-v7-04-k1","title":"原理與限制","titleEn":"Principle and limits","text":"電源網路有寄生電感與電容，暫態不能只用電阻描述。","textEn":"Parasitic inductance and capacitance make transient behavior more than resistance."},{"id":"a025-v7-04-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"不同量測頻寬會改變可見的快速事件。","textEn":"Measurement bandwidth changes which fast events are visible."}],"quiz":{"question":"平均電壓相同能證明瞬態相同嗎？","questionEn":"Does equal average voltage prove equal transients?","options":["不能，需比較谷值與時間響應。","能，平均值涵蓋全部頻率。","能，只要晶片尺寸相同。"],"optionsEn":["No; compare minima and timing.","Yes; averages capture every frequency.","Yes, if die size matches."],"answer":0,"explanation":"不能，需比較谷值與時間響應。 電源網路有寄生電感與電容，暫態不能只用電阻描述。","explanationEn":"No; compare minima and timing. Parasitic inductance and capacitance make transient behavior more than resistance."}},{"id":"a025-v7-05","order":5,"sequence":5,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-dtco"],"prerequisiteIds":["a025-v7-04"],"title":"檢查標準元件配線容量","titleEn":"Inspect standard-cell routing capacity","objective":"評估釋放電源軌空間的實際收益。","objectiveEn":"Evaluate usable space released by power routing.","instruction":"畫四個相鄰標準元件；分開標記電源軌與訊號軌；移動電源後重新連接訊號；記錄仍因通孔或禁佈區受限的位置。","instructionEn":"Draw four adjacent cells; mark power and signal tracks separately; reroute signals after relocating power; record remaining via and keep-out constraints.","observation":"可用面積增加不等於所有線都能順利佈完。","observationEn":"More area does not guarantee routability.","failure":"若只按面積比例推算頻率，增加實際線長與擁塞比較。","failureEn":"If frequency is inferred from area alone, add route-length and congestion checks.","check":"交付前後配置及一處仍未解決的擁塞。","checkEn":"Submit before/after layouts and one remaining congestion point.","knowledge":[{"id":"a025-v7-05-k1","title":"原理與限制","titleEn":"Principle and limits","text":"設計與技術協同最佳化需同時考慮元件與配線限制。","textEn":"Design-technology co-optimization considers cells and routing together."},{"id":"a025-v7-05-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"面積、速度、功耗的比較必須使用一致工作負載與限制。","textEn":"Area, speed and power comparisons need matching workloads and constraints."}],"quiz":{"question":"釋放面積後應再驗證什麼？","questionEn":"What should be checked after space is released?","options":["只看空白面積就宣告性能提升。","訊號能否佈通以及路徑延遲。","刪除所有禁佈區以完成比較。"],"optionsEn":["Declare performance from blank area alone.","Signal routability and path delay.","Remove all keep-outs to finish comparison."],"answer":1,"explanation":"訊號能否佈通以及路徑延遲。 設計與技術協同最佳化需同時考慮元件與配線限制。","explanationEn":"Signal routability and path delay. Design-technology co-optimization considers cells and routing together."}},{"id":"a025-v7-06","order":6,"sequence":6,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-intel"],"prerequisiteIds":["a025-v7-05"],"title":"選擇測試載具與對照組","titleEn":"Select test vehicles and controls","objective":"把新供電技術與電晶體改版的影響分離。","objectiveEn":"Separate delivery changes from transistor changes.","instruction":"列出電晶體、電源網路及工作負載三項變因；設計只改供電的對照；指定前後量測；記錄尚不能歸因的差異。","instructionEn":"List transistor, delivery network and workload variables; design a delivery-only comparison; specify before/after measurements; record unattributable differences.","observation":"同時更改多項技術會混淆原因。","observationEn":"Changing several technologies confounds attribution.","failure":"若對照的尺寸與溫度不同，先統一條件再比較。","failureEn":"Match geometry and temperature before comparing controls.","check":"一張實驗矩陣說明固定、改變及量測項。","checkEn":"Provide a matrix of fixed, changed and measured items.","knowledge":[{"id":"a025-v7-06-k1","title":"原理與限制","titleEn":"Principle and limits","text":"測試載具可先驗證單一整合風險。","textEn":"A test vehicle can isolate an integration risk."},{"id":"a025-v7-06-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"研究晶片的改善不自動等於產品在所有負載下的改善。","textEn":"Test-chip gains are not automatic product gains under every workload."}],"quiz":{"question":"只想判斷背面供電效益，應如何設計？","questionEn":"How should a delivery-specific benefit be tested?","options":["同時更换架構與工作負載。","只挑表現最好的一筆數據。","保持其他主要變因一致。"],"optionsEn":["Change architecture and workload simultaneously.","Select only the best measurement.","Keep other major variables comparable."],"answer":2,"explanation":"保持其他主要變因一致。 測試載具可先驗證單一整合風險。","explanationEn":"Keep other major variables comparable. A test vehicle can isolate an integration risk."}}]},{"id":"a025-stage02","order":2,"title":"鍵合、薄化與前後對準","titleEn":"Bonding, thinning and alignment","description":"用截面與誤差帳本理解背面加工的依存關係。","descriptionEn":"Use sections and error budgets to understand backside integration dependencies.","steps":[{"id":"a025-v7-07","order":1,"sequence":7,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-flow"],"prerequisiteIds":["a025-v7-06"],"title":"建立前後面方向與標記","titleEn":"Establish front/back orientation and marks","objective":"避免翻面後座標與極性誤判。","objectiveEn":"Avoid coordinate and polarity errors after flipping.","instruction":"畫俯視與截面基準；標出缺口與三個不對稱標記；紙上翻面後重標座標；追蹤同一 VDD 接點的位置。","instructionEn":"Draw plan and section references; add a notch and three asymmetric marks; relabel coordinates after a paper flip; track the same VDD contact.","observation":"翻轉與平面旋轉對圖案的影響不同。","observationEn":"A flip and an in-plane rotation transform patterns differently.","failure":"對稱標記無法辨認鏡像時，增加不對稱識別。","failureEn":"Add an asymmetric identifier if marks cannot distinguish mirroring.","check":"兩視圖間同一接點能唯一對應。","checkEn":"Each contact has one unambiguous cross-view match.","knowledge":[{"id":"a025-v7-07-k1","title":"原理與限制","titleEn":"Principle and limits","text":"背面加工需要將量測座標連回正面元件。","textEn":"Backside processing must relate measurements to frontside devices."},{"id":"a025-v7-07-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"標記本身也需在薄化及堆疊後可辨識。","textEn":"Marks must remain identifiable after thinning and stacking."}],"quiz":{"question":"哪種標記較能揭露翻面錯誤？","questionEn":"Which mark best exposes a flip error?","options":["可區分鏡像的不對稱標記。","完全均勻的圓。","沒有方向定義的網格。"],"optionsEn":["An asymmetric mark that distinguishes mirrors.","A uniform circle.","A grid without orientation."],"answer":0,"explanation":"可區分鏡像的不對稱標記。 背面加工需要將量測座標連回正面元件。","explanationEn":"An asymmetric mark that distinguishes mirrors. Backside processing must relate measurements to frontside devices."}},{"id":"a025-v7-08","order":2,"sequence":8,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-flow"],"prerequisiteIds":["a025-v7-07"],"title":"規劃載板鍵合的支撐","titleEn":"Plan carrier-bond support","objective":"理解薄晶圓加工的機械邊界。","objectiveEn":"Understand mechanical boundaries during thin-wafer processing.","instruction":"畫主動晶圓與載板的接合面；標出後續加工施力位置；比較完全支撐與局部空隙；建立加工前空隙檢查清單。","instructionEn":"Draw active wafer and carrier interfaces; mark later loading locations; compare full support with a local void; create a pre-processing void check.","observation":"局部失去支撐可能造成厚度或應力異常。","observationEn":"A local support gap can produce thickness or stress anomalies.","failure":"不能以外側貼合外觀證明內部無空隙；指定適合的非破壞檢查。","failureEn":"Outer appearance does not establish void-free bonding; specify suitable nondestructive inspection.","check":"示意圖標明支撐、空隙與驗證位置。","checkEn":"Label support, voids and inspection positions.","knowledge":[{"id":"a025-v7-08-k1","title":"原理與限制","titleEn":"Principle and limits","text":"載板提供薄化期間的機械支撐。","textEn":"A carrier provides support during thinning."},{"id":"a025-v7-08-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"鍵合平整度也會影響後續對準與量測。","textEn":"Bond geometry also affects later alignment and measurement."}],"quiz":{"question":"局部空隙最先影響哪種假設？","questionEn":"Which assumption is challenged by a local void?","options":["電晶體數量固定。","晶圓各處具有一致支撐。","所有訊號都在背面。"],"optionsEn":["A fixed transistor count.","Uniform support across the wafer.","All signals being backside."],"answer":1,"explanation":"晶圓各處具有一致支撐。 載板提供薄化期間的機械支撐。","explanationEn":"Uniform support across the wafer. A carrier provides support during thinning."}},{"id":"a025-v7-09","order":3,"sequence":9,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-flow"],"prerequisiteIds":["a025-v7-08"],"title":"分配薄化餘量","titleEn":"Allocate thinning margin","objective":"用最薄區而非平均值控制去除預算。","objectiveEn":"Budget removal using local minima, not only averages.","instruction":"建立九點假設厚度圖；列出粗去除、精修與終點餘量；逐點相減；標記最先失去餘量的區域。","instructionEn":"Create a hypothetical nine-point thickness map; allocate coarse removal, finishing and endpoint margin; subtract pointwise; mark the first region to lose margin.","observation":"平均厚度合格時仍可能有局部過薄。","observationEn":"Local over-thinning can occur despite an acceptable average.","failure":"若用單一平均值，回到位置配對的前後圖。","failureEn":"Replace an average-only analysis with paired spatial maps.","check":"每區剩餘量非負，且列出需重檢的極值。","checkEn":"Each region retains nonnegative margin and flagged extrema are listed.","knowledge":[{"id":"a025-v7-09-k1","title":"原理與限制","titleEn":"Principle and limits","text":"材料去除不可由後續拋光補回。","textEn":"Subsequent polishing cannot restore removed material."},{"id":"a025-v7-09-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"終點需符合元件與接觸設計，不是越薄越好。","textEn":"The endpoint must suit device and contact design; thinner is not always better."}],"quiz":{"question":"薄化應優先留意哪項？","questionEn":"What deserves priority during thinning review?","options":["照片最亮的區域。","僅全片平均加工時間。","局部最小剩餘厚度。"],"optionsEn":["The brightest photo region.","Only average processing time.","Minimum local remaining thickness."],"answer":2,"explanation":"局部最小剩餘厚度。 材料去除不可由後續拋光補回。","explanationEn":"Minimum local remaining thickness. Subsequent polishing cannot restore removed material."}},{"id":"a025-v7-10","order":4,"sequence":10,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-building"],"prerequisiteIds":["a025-v7-09"],"title":"辨認薄化終點證據","titleEn":"Identify thinning-endpoint evidence","objective":"區分厚度讀值與露出目標層。","objectiveEn":"Distinguish thickness readings from target-layer exposure.","instruction":"畫三種截面：未到、剛到與過度去除；為各截面選擇厚度或材料辨識證據；比較中心與邊緣結果；標示不能由光澤判定的部分。","instructionEn":"Draw under-thinned, target and over-thinned sections; choose thickness or material-identification evidence; compare center and edge; mark what gloss cannot establish.","observation":"幾何厚度與材料種類回答不同問題。","observationEn":"Geometry and material identity answer different questions.","failure":"未證實目標層前，不把時間到了當成終點。","failureEn":"Do not treat elapsed time as proof of target-layer exposure.","check":"三種截面各有可區分的量測判據。","checkEn":"Each section has a discriminating measurement criterion.","knowledge":[{"id":"a025-v7-10-k1","title":"原理與限制","titleEn":"Principle and limits","text":"薄化流程需要可重複的終點指標。","textEn":"A thinning flow needs a reproducible endpoint indicator."},{"id":"a025-v7-10-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"量測需保留校正與空間範圍，才能比較不同區域。","textEn":"Calibration and spatial extent are needed to compare regions."}],"quiz":{"question":"只看加工時間可否證明已露出目標層？","questionEn":"Does processing time prove the target layer is exposed?","options":["不能，需材料或厚度證據。","可以，相同時間一定相同厚度。","可以，背面顏色一定唯一。"],"optionsEn":["No; material or thickness evidence is needed.","Yes; equal time guarantees equal thickness.","Yes; backside color is always unique."],"answer":0,"explanation":"不能，需材料或厚度證據。 薄化流程需要可重複的終點指標。","explanationEn":"No; material or thickness evidence is needed. A thinning flow needs a reproducible endpoint indicator."}},{"id":"a025-v7-11","order":5,"sequence":11,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-flow"],"prerequisiteIds":["a025-v7-10"],"title":"分解前後側對準誤差","titleEn":"Decompose front-to-back overlay error","objective":"辨認全片位移與局部形變。","objectiveEn":"Distinguish global offsets from local distortion.","instruction":"在九個位置畫設計與實測標記；先扣除共同平移；再比較旋轉與殘差；把局部不規則量保留為未解釋項。","instructionEn":"Draw designed and measured marks at nine sites; remove common translation; compare rotation and residuals; retain irregular local errors as unexplained.","observation":"消除平均偏差後仍可能有局部錯位。","observationEn":"Local misalignment can remain after average offset removal.","failure":"只報平均誤差可能抵消正負值；增加最大值與位置圖。","failureEn":"Signed errors can cancel in averages; add maxima and maps.","check":"提交原始、校正後及殘差三張圖。","checkEn":"Submit raw, corrected and residual maps.","knowledge":[{"id":"a025-v7-11-k1","title":"原理與限制","titleEn":"Principle and limits","text":"鍵合形變可能影響後續微影對準。","textEn":"Bond-induced distortion can affect later lithographic alignment."},{"id":"a025-v7-11-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"誤差預算應保留量測不確定度。","textEn":"An error budget should retain measurement uncertainty."}],"quiz":{"question":"平均位移為零代表全部對準嗎？","questionEn":"Does zero mean offset prove alignment everywhere?","options":["代表，正負誤差已物理消失。","不代表，局部殘差可能存在。","代表，旋轉不影响接點。"],"optionsEn":["Yes; opposite errors have physically vanished.","No; local residuals may remain.","Yes; rotation cannot affect contacts."],"answer":1,"explanation":"不代表，局部殘差可能存在。 鍵合形變可能影響後續微影對準。","explanationEn":"No; local residuals may remain. Bond-induced distortion can affect later lithographic alignment."}},{"id":"a025-v7-12","order":6,"sequence":12,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-demo","v7-bspdn-building"],"prerequisiteIds":["a025-v7-11"],"title":"審查前段元件相容性","titleEn":"Review compatibility with frontside devices","objective":"將新增加工視為可驗證的應力來源。","objectiveEn":"Treat additional processing as a testable stress source.","instruction":"列出鍵合、薄化、背面加工三個節點；為每節點指定前後電性量測；固定量測溫度；對照一組未做新增流程的測試元件。","instructionEn":"List bonding, thinning and backside-processing checkpoints; assign before/after electrical tests; fix test temperature; compare controls without the added flow.","observation":"結果變化應與流程節點和量測條件關聯。","observationEn":"Changes should be related to process checkpoints and measurement conditions.","failure":"不同量測溫度可能製造假退化；先核對測試條件。","failureEn":"Different test temperatures can mimic degradation; verify conditions first.","check":"差異表能區分元件變化與量測漂移。","checkEn":"The comparison distinguishes device changes from measurement drift.","knowledge":[{"id":"a025-v7-12-k1","title":"原理與限制","titleEn":"Principle and limits","text":"未退化的研究展示只適用其測試條件。","textEn":"A non-degradation result applies to its tested conditions."},{"id":"a025-v7-12-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"前後配對比獨立批次平均更能定位變化。","textEn":"Paired before/after data can localize changes better than separate batch averages."}],"quiz":{"question":"某研究元件未退化，可否保證所有產品？","questionEn":"Does one non-degraded research device guarantee every product?","options":["可以，薄化永遠無影響。","可以，電性只由正面尺寸決定。","不能，需依各整合條件再驗證。"],"optionsEn":["Yes; thinning never matters.","Yes; frontside dimensions alone determine behavior.","No; each integration needs verification."],"answer":2,"explanation":"不能，需依各整合條件再驗證。 未退化的研究展示只適用其測試條件。","explanationEn":"No; each integration needs verification. A non-degradation result applies to its tested conditions."}}]},{"id":"a025-stage03","order":3,"title":"背面接觸與配線整合","titleEn":"Backside contacts and routing","description":"檢查連接、絕緣、熱路徑及製程相容性。","descriptionEn":"Review connectivity, insulation, thermal paths and process compatibility.","steps":[{"id":"a025-v7-13","order":1,"sequence":13,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-dtco"],"prerequisiteIds":["a025-v7-12"],"title":"比較埋藏軌與直接接觸","titleEn":"Compare buried-rail and direct-contact schemes","objective":"辨識不同背面連接策略的介面。","objectiveEn":"Identify interfaces in alternative backside connections.","instruction":"畫背面通孔接埋藏軌的路徑；另畫直接接近源汲極的概念路徑；比較落點面積；列出隔離與對準問題，避免混用兩種流程。","instructionEn":"Draw a backside via landing on a buried rail; sketch a conceptual direct device connection; compare landing areas; list isolation and alignment concerns without mixing flows.","observation":"不同方案可共享目標但不共享所有步驟。","observationEn":"Schemes can share goals without sharing every process step.","failure":"若移植一個方案的規則，先確認結構是否相同。","failureEn":"Check structural equivalence before transferring a rule.","check":"以介面表說明兩者共同點與差異。","checkEn":"Provide an interface table of similarities and differences.","knowledge":[{"id":"a025-v7-13-k1","title":"原理與限制","titleEn":"Principle and limits","text":"背面連接不是單一固定架構。","textEn":"Backside connectivity is not one fixed architecture."},{"id":"a025-v7-13-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"較短路徑仍需付出可製造性與隔離驗證。","textEn":"A shorter path still requires manufacturability and isolation verification."}],"quiz":{"question":"兩種方案可直接共用完整流程嗎？","questionEn":"Can both schemes use an identical complete flow?","options":["不能，落點與隔離結構不同。","可以，只需更改名稱。","可以，通孔不需要對準。"],"optionsEn":["No; landing and isolation structures differ.","Yes; rename the process.","Yes; vias need no alignment."],"answer":0,"explanation":"不能，落點與隔離結構不同。 背面連接不是單一固定架構。","explanationEn":"No; landing and isolation structures differ. Backside connectivity is not one fixed architecture."}},{"id":"a025-v7-14","order":2,"sequence":14,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-demo"],"prerequisiteIds":["a025-v7-13"],"title":"檢查通孔的絕緣與導通","titleEn":"Inspect via isolation and continuity","objective":"分開開路、短路與高阻三種缺陷。","objectiveEn":"Separate open, shorted and high-resistance faults.","instruction":"畫正常、填充空隙、側壁隔離破損三個截面；逐一預測導通與漏電結果；把電性結果配回截面；提出可排除另一原因的追加檢查。","instructionEn":"Draw sound, voided and insulation-damaged vias; predict continuity and leakage; match results to sections; propose a check excluding an alternative cause.","observation":"導通良好不代表與鄰近結構隔離良好。","observationEn":"Good continuity does not prove isolation from neighbors.","failure":"若只測通斷，增加隔離證據，不據此猜測材料配方。","failureEn":"Add isolation evidence to continuity testing; do not infer a recipe.","check":"缺陷矩陣包含導通、電阻及隔離三欄。","checkEn":"The fault matrix includes continuity, resistance and isolation.","knowledge":[{"id":"a025-v7-14-k1","title":"原理與限制","titleEn":"Principle and limits","text":"導電路徑與隔離邊界需同時成立。","textEn":"The conductive path and insulating boundary must both work."},{"id":"a025-v7-14-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"不同缺陷可能有相同單一測試結果。","textEn":"Different defects can share a single test signature."}],"quiz":{"question":"只測到導通足以放行嗎？","questionEn":"Is continuity alone enough for release?","options":["足夠，短路也算完成連接。","不足，還須檢查電阻及隔離。","足夠，漏電只發生於正面。"],"optionsEn":["Yes; a short also counts as connection.","No; resistance and isolation also matter.","Yes; leakage occurs only on the front."],"answer":1,"explanation":"不足，還須檢查電阻及隔離。 導電路徑與隔離邊界需同時成立。","explanationEn":"No; resistance and isolation also matter. The conductive path and insulating boundary must both work."}},{"id":"a025-v7-15","order":3,"sequence":15,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-demo"],"prerequisiteIds":["a025-v7-14"],"title":"建立接觸電阻的比較","titleEn":"Build a contact-resistance comparison","objective":"避免把線路電阻誤當成接觸電阻。","objectiveEn":"Avoid confusing line resistance with contact resistance.","instruction":"畫兩端量測含引線的模型；再畫四端感測的概念配置；給引線相同假設增量；比較兩種讀值受影響程度。","instructionEn":"Draw a two-terminal model including leads; sketch conceptual four-terminal sensing; add the same hypothetical lead resistance; compare measurement sensitivity.","observation":"測到的總阻值可能含測試結構本身。","observationEn":"Measured resistance can include the test structure.","failure":"若沒有結構資訊，將結果標為總路徑阻值。","failureEn":"Without structure information, label the value total-path resistance.","check":"報告說明感測點與未扣除的寄生項。","checkEn":"State sensing locations and unremoved parasitics.","knowledge":[{"id":"a025-v7-15-k1","title":"原理與限制","titleEn":"Principle and limits","text":"接觸、通孔與金屬線共同形成路徑電阻。","textEn":"Contacts, vias and lines contribute to path resistance."},{"id":"a025-v7-15-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"量測方法影響可分離出的物理量。","textEn":"The measurement method determines which quantities can be isolated."}],"quiz":{"question":"兩端讀值增加一定代表接觸退化嗎？","questionEn":"Does higher two-terminal resistance prove contact degradation?","options":["一定，線路不可能有電阻。","一定，探針接觸永遠理想。","不一定，引線與通孔也可能改變。"],"optionsEn":["Yes; lines cannot have resistance.","Yes; probe contact is always ideal.","No; leads or vias may also have changed."],"answer":2,"explanation":"不一定，引線與通孔也可能改變。 接觸、通孔與金屬線共同形成路徑電阻。","explanationEn":"No; leads or vias may also have changed. Contacts, vias and lines contribute to path resistance."}},{"id":"a025-v7-16","order":4,"sequence":16,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-dtco"],"prerequisiteIds":["a025-v7-15"],"title":"規劃背面金屬網路","titleEn":"Plan the backside metal network","objective":"平衡供電覆蓋、壓降與區域需求。","objectiveEn":"Balance power coverage, drop and regional demand.","instruction":"把假設晶片分成四個負載區；分配電源入口與網格；用相同總金屬量比較均勻與偏重熱點的方案；檢查最遠路徑。","instructionEn":"Divide a hypothetical die into four load zones; place entries and a grid; compare uniform and hotspot-weighted metal at equal total amount; inspect the longest path.","observation":"相同金屬總量可以有不同最差壓降。","observationEn":"Equal metal quantity can produce different worst-case drops.","failure":"若只最佳化平均值，重新檢查最高負載與邊角區。","failureEn":"After average-only optimization, revisit peak-load and corner regions.","check":"交出兩方案的負載圖、路徑與取捨。","checkEn":"Submit load maps, paths and tradeoffs for both schemes.","knowledge":[{"id":"a025-v7-16-k1","title":"原理與限制","titleEn":"Principle and limits","text":"供電網路需配合負載空間分布。","textEn":"Power routing should match spatial load demand."},{"id":"a025-v7-16-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"電源入口位置與網格密度共同影響路徑。","textEn":"Entry locations and grid density jointly shape paths."}],"quiz":{"question":"相同總金屬量是否代表相同供電品質？","questionEn":"Does equal metal quantity imply equal delivery quality?","options":["否，配置與負載分布仍不同。","是，只要面積相同。","是，電流均勻分配與負載無關。"],"optionsEn":["No; topology and load distribution differ.","Yes, provided area matches.","Yes; current divides independently of load."],"answer":0,"explanation":"否，配置與負載分布仍不同。 供電網路需配合負載空間分布。","explanationEn":"No; topology and load distribution differ. Power routing should match spatial load demand."}},{"id":"a025-v7-17","order":5,"sequence":17,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-demo"],"prerequisiteIds":["a025-v7-16"],"title":"追蹤去耦電容的作用","titleEn":"Trace the role of decoupling capacitance","objective":"把暫態支援與直流供電分開。","objectiveEn":"Separate transient support from steady power supply.","instruction":"畫負載、寄生路徑與去耦支路；假設同一電流脈衝；比較電容靠近與遠離負載的回路；標出寄生電感可能削弱效果的位置。","instructionEn":"Draw the load, parasitic path and decoupling branch; apply the same hypothetical current pulse; compare near and distant loops; mark where inductance weakens the response.","observation":"加大電容不能自動消除所有頻率的阻抗。","observationEn":"Increasing capacitance does not eliminate impedance at every frequency.","failure":"若只列電容量，補回連接路徑及頻率條件。","failureEn":"Add connection-path and frequency conditions to capacitance alone.","check":"以回路圖解释一種配置較有效的原因。","checkEn":"Explain a configuration advantage using a loop diagram.","knowledge":[{"id":"a025-v7-17-k1","title":"原理與限制","titleEn":"Principle and limits","text":"去耦提供短時間能量緩衝。","textEn":"Decoupling provides a short-term energy buffer."},{"id":"a025-v7-17-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"電容位置、連接寄生與負載頻譜同樣重要。","textEn":"Location, connection parasitics and load spectrum also matter."}],"quiz":{"question":"比較去耦方案時還需什麼？","questionEn":"What else matters when comparing decoupling?","options":["只有標稱電容量。","連接回路與頻率範圍。","只看電容顏色。"],"optionsEn":["Only nominal capacitance.","Connection loop and frequency range.","Only capacitor color."],"answer":1,"explanation":"連接回路與頻率範圍。 去耦提供短時間能量緩衝。","explanationEn":"Connection loop and frequency range. Decoupling provides a short-term energy buffer."}},{"id":"a025-v7-18","order":6,"sequence":18,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-esd"],"prerequisiteIds":["a025-v7-17"],"title":"審查散熱與薄基板","titleEn":"Review heat flow through a thin substrate","objective":"辨認薄化如何改變熱擴散路徑。","objectiveEn":"Identify how thinning changes heat spreading.","instruction":"畫元件、薄矽、背面金屬與封裝的熱路徑；分別標熱源及散熱邊界；比較兩種金屬分布；列出需模擬的局部溫升。","instructionEn":"Draw thermal paths through devices, thin silicon, backside metal and package; mark sources and sinks; compare two metal layouts; list local temperature rises needing simulation.","observation":"較低電阻不保證每個熱點都更冷。","observationEn":"Lower resistance does not guarantee every hotspot is cooler.","failure":"若宣稱薄化一定改善散熱，重新比較垂直與橫向路徑。","failureEn":"Revisit vertical and lateral paths before claiming thinning always improves cooling.","check":"熱路徑圖清楚區分電性收益與熱風險。","checkEn":"The diagram separates electrical benefits from thermal risks.","knowledge":[{"id":"a025-v7-18-k1","title":"原理與限制","titleEn":"Principle and limits","text":"薄化會改變原本矽基板的熱擴散能力。","textEn":"Thinning changes heat spreading through silicon."},{"id":"a025-v7-18-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"背面金屬可能提供新熱路徑，但需依幾何驗證。","textEn":"Backside metal can provide new thermal paths, subject to geometry."}],"quiz":{"question":"背面供電電阻降低就一定不過熱嗎？","questionEn":"Does lower delivery resistance rule out overheating?","options":["一定，電阻是唯一熱參數。","一定，薄矽沒有熱容量。","不一定，仍需熱模型與邊界條件。"],"optionsEn":["Yes; resistance is the only thermal parameter.","Yes; thin silicon has no heat capacity.","No; a thermal model and boundaries are needed."],"answer":2,"explanation":"不一定，仍需熱模型與邊界條件。 薄化會改變原本矽基板的熱擴散能力。","explanationEn":"No; a thermal model and boundaries are needed. Thinning changes heat spreading through silicon."}}]},{"id":"a025-stage04","order":4,"title":"電性、可靠度與設計審查","titleEn":"Electrical, reliability and design review","description":"以對照組、失效定位與交付證據判讀方案。","descriptionEn":"Evaluate the design through controls, failure localization and release evidence.","steps":[{"id":"a025-v7-19","order":1,"sequence":19,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-building"],"prerequisiteIds":["a025-v7-18"],"title":"建立晶圓內電性地圖","titleEn":"Build a within-wafer electrical map","objective":"區分共同偏移與局部缺陷。","objectiveEn":"Separate shared shifts from local faults.","instruction":"在九點地圖填假設通孔電阻；標記加工前後差值；比較邊緣與中心；檢查異常是否與厚度或對準殘差共位。","instructionEn":"Place hypothetical via resistances on a nine-site map; calculate before/after changes; compare edge and center; check co-location with thickness or overlay residuals.","observation":"相關位置可提出假說，不能單獨證明原因。","observationEn":"Spatial correlation suggests a hypothesis but does not prove causation.","failure":"若只挑單點最佳結果，恢復全圖及失敗點。","failureEn":"Restore the full map and failures if only the best point was selected.","check":"每個異常有位置、對照項及追加檢查。","checkEn":"Each anomaly has a location, comparator and follow-up check.","knowledge":[{"id":"a025-v7-19-k1","title":"原理與限制","titleEn":"Principle and limits","text":"位置配對能串接多種量測證據。","textEn":"Spatial pairing connects different measurement evidence."},{"id":"a025-v7-19-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"全片均值會掩蓋局部短路或高阻。","textEn":"A whole-wafer average can hide local shorts or high resistance."}],"quiz":{"question":"異常電阻和薄區重疊代表什麼？","questionEn":"What does resistance/thickness co-location establish?","options":["值得追查的關聯，尚非因果證明。","已證明唯一失效原因。","所有其他量測都不必要。"],"optionsEn":["A useful association, not yet causation.","The sole failure cause is proven.","All other measurements are unnecessary."],"answer":0,"explanation":"值得追查的關聯，尚非因果證明。 位置配對能串接多種量測證據。","explanationEn":"A useful association, not yet causation. Spatial pairing connects different measurement evidence."}},{"id":"a025-v7-20","order":2,"sequence":20,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-demo"],"prerequisiteIds":["a025-v7-19"],"title":"比較電流密度與可靠度","titleEn":"Compare current density and reliability","objective":"將截面瓶頸與壽命評估連起來。","objectiveEn":"Connect cross-sectional bottlenecks to reliability review.","instruction":"畫兩種不同截面接點；用假設 I/A 比較平均電流密度；圈出轉角及縮頸；列出溫度與時間需一併記錄的理由。","instructionEn":"Draw contacts with two cross-sections; compare hypothetical I/A averages; circle corners and necks; explain why temperature and duration must also be recorded.","observation":"平均密度未反映所有局部擁擠。","observationEn":"Average density does not capture all local crowding.","failure":"勿把簡化比值直接換成壽命；保留材料與幾何未知項。","failureEn":"Do not convert a simple ratio into lifetime; retain material and geometry uncertainties.","check":"結果只排序風險，不虛構產品壽命。","checkEn":"Results rank concerns without inventing product lifetime.","knowledge":[{"id":"a025-v7-20-k1","title":"原理與限制","titleEn":"Principle and limits","text":"較小有效截面在相同電流下有較高平均電流密度。","textEn":"A smaller effective area has higher average density at equal current."},{"id":"a025-v7-20-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"可靠度需要時間、溫度與局部結構的聯合證據。","textEn":"Reliability needs evidence about duration, temperature and local structure."}],"quiz":{"question":"I/A 可以直接算出產品壽命嗎？","questionEn":"Can I/A alone determine product lifetime?","options":["可以，與溫度無關。","不能，它只是風險分析的一部分。","可以，所有材料完全相同。"],"optionsEn":["Yes; temperature is irrelevant.","No; it is one part of the analysis.","Yes; all materials behave identically."],"answer":1,"explanation":"不能，它只是風險分析的一部分。 較小有效截面在相同電流下有較高平均電流密度。","explanationEn":"No; it is one part of the analysis. A smaller effective area has higher average density at equal current."}},{"id":"a025-v7-21","order":3,"sequence":21,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-esd"],"prerequisiteIds":["a025-v7-20"],"title":"規劃 ESD 保護路徑","titleEn":"Plan the ESD protection path","objective":"理解保護導通與熱承受是不同條件。","objectiveEn":"Distinguish protection conduction from thermal survival.","instruction":"畫正常供電與瞬態放電路徑；標出保護元件及回流；比較薄化前後的散熱體積；建立僅供模型審查的失效假說。","instructionEn":"Draw normal power and transient discharge paths; mark protection devices and return; compare heat-spreading volume before/after thinning; form model-review failure hypotheses.","observation":"保護元件能導通仍可能局部過熱。","observationEn":"A conducting protection device can still overheat locally.","failure":"不在真實晶片施加放電；用公開原理及假設模型討論。","failureEn":"Do not discharge real chips; discuss public principles and hypothetical models.","check":"圖中同時標示電流與熱兩條路徑。","checkEn":"The diagram includes electrical and thermal paths.","knowledge":[{"id":"a025-v7-21-k1","title":"原理與限制","titleEn":"Principle and limits","text":"ESD 防護需同時處理電流分流與能量散逸。","textEn":"ESD protection addresses both current diversion and energy dissipation."},{"id":"a025-v7-21-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"薄基板的保護策略需重新檢查熱限制。","textEn":"Thin-substrate protection requires renewed thermal review."}],"quiz":{"question":"導通測試通過便代表 ESD 保護完整嗎？","questionEn":"Does passing continuity establish complete ESD protection?","options":["代表，放電完全沒有熱。","代表，薄化不改變材料體積。","不代表，熱承受與路徑仍需驗證。"],"optionsEn":["Yes; discharge produces no heat.","Yes; thinning changes no volume.","No; thermal survival and pathways still need checks."],"answer":2,"explanation":"不代表，熱承受與路徑仍需驗證。 ESD 防護需同時處理電流分流與能量散逸。","explanationEn":"No; thermal survival and pathways still need checks. ESD protection addresses both current diversion and energy dissipation."}},{"id":"a025-v7-22","order":4,"sequence":22,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-dtco","v7-bspdn-demo"],"prerequisiteIds":["a025-v7-21"],"title":"建立失效定位決策樹","titleEn":"Build a failure-localization tree","objective":"以最少追加證據分辨可能原因。","objectiveEn":"Distinguish causes with targeted additional evidence.","instruction":"從高壓降案例出發列出高負載、高阻與量測偏移；為每支假說選一個可否證觀察；依非破壞性排檢查順序；記錄哪些結論仍不確定。","instructionEn":"Start with excessive drop and list high load, high resistance and measurement offset; choose a falsifying observation per branch; order nondestructive checks; record unresolved conclusions.","observation":"同一症狀可以來自不同子系統。","observationEn":"One symptom can originate in different subsystems.","failure":"若直接把異常歸為薄化失敗，補上排除負載及測試偏差的證據。","failureEn":"Exclude load and measurement changes before blaming thinning.","check":"每支分支有輸入、判据與後續動作。","checkEn":"Each branch has input, criterion and follow-up action.","knowledge":[{"id":"a025-v7-22-k1","title":"原理與限制","titleEn":"Principle and limits","text":"診斷流程應區分症狀與物理原因。","textEn":"Diagnosis distinguishes symptoms from physical causes."},{"id":"a025-v7-22-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"有效檢查需能改變判斷，而非重複同一讀值。","textEn":"A useful check changes the inference instead of repeating the same value."}],"quiz":{"question":"高壓降首先證明哪件事？","questionEn":"What does excessive drop establish first?","options":["供電表現異常，原因仍需區分。","一定是通孔空隙。","一定是背面微影失效。"],"optionsEn":["Delivery is abnormal; the cause remains to be distinguished.","It must be a via void.","It must be backside lithography failure."],"answer":0,"explanation":"供電表現異常，原因仍需區分。 診斷流程應區分症狀與物理原因。","explanationEn":"Delivery is abnormal; the cause remains to be distinguished. Diagnosis distinguishes symptoms from physical causes."}},{"id":"a025-v7-23","order":5,"sequence":23,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-flow","v7-bspdn-dtco"],"prerequisiteIds":["a025-v7-22"],"title":"連結混合鍵合與封裝課程","titleEn":"Connect hybrid bonding and packaging","objective":"比較共享的介面問題與不同功能。","objectiveEn":"Compare shared interface problems and different functions.","instruction":"把背面供電、晶圓混合鍵合及先進封裝排在一張介面圖；圈出對準、平坦度與連接電阻共同項；標示訊號與電源目標差異；選一個衍生課程繼續。","instructionEn":"Place backside power, wafer hybrid bonding and advanced packaging on one interface map; circle alignment, flatness and resistance concerns; distinguish signal and power goals; choose a related course.","observation":"共用量測觀念不表示可互換流程。","observationEn":"Shared metrology concepts do not make flows interchangeable.","failure":"若直接套用鍵合間距，先核對接點用途與結構。","failureEn":"Verify contact purpose and structure before transferring a bonding pitch.","check":"比較表至少列出兩共同點與一差異。","checkEn":"List at least two similarities and one difference.","knowledge":[{"id":"a025-v7-23-k1","title":"原理與限制","titleEn":"Principle and limits","text":"多層整合共同依賴清楚的介面定義。","textEn":"Multilevel integration relies on clear interface definitions."},{"id":"a025-v7-23-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"同一量測名稱在不同尺度下仍需重新定義取樣範圍。","textEn":"The same measurement name still needs a scale-specific sampling definition."}],"quiz":{"question":"相似工法最適合轉移什麼？","questionEn":"What transfers best between related processes?","options":["整套未知設備設定。","問題分析與驗證方法，再確認適用條件。","所有幾何尺寸直接照搬。"],"optionsEn":["An entire unknown equipment setup.","Analysis and verification methods, with applicability checked.","Every geometry copied unchanged."],"answer":1,"explanation":"問題分析與驗證方法，再確認適用條件。 多層整合共同依賴清楚的介面定義。","explanationEn":"Analysis and verification methods, with applicability checked. Multilevel integration relies on clear interface definitions."}},{"id":"a025-v7-24","order":6,"sequence":24,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v7-bspdn-intel","v7-bspdn-demo"],"prerequisiteIds":["a025-v7-23"],"title":"完成總工程師整合審查","titleEn":"Complete the chief-engineer integration review","objective":"建立可追溯且不誇大結論的交付包。","objectiveEn":"Produce a traceable review package without overstating results.","instruction":"整理截面、壓降帳本與對準地圖；列出三項已驗證及三項未知；提出下一輪對照實驗；用一頁說明放行或暫緩的理由。","instructionEn":"Collect sections, drop ledger and overlay maps; list three verified and three unknown items; propose the next controlled comparison; justify release or hold on one page.","observation":"證據完整度與性能數字大小是兩回事。","observationEn":"Evidence completeness differs from the size of a performance gain.","failure":"沒有實測或有效模型的項目維持待驗證，不填入廠商保證。","failureEn":"Keep unsupported items unverified rather than adding manufacturer guarantees.","check":"每项結論可連回來源、假設或自己的計算。","checkEn":"Every conclusion traces to a source, assumption or calculation.","knowledge":[{"id":"a025-v7-24-k1","title":"原理與限制","titleEn":"Principle and limits","text":"設計審查評估證據與限制，不只展示最漂亮的結果。","textEn":"Design review evaluates evidence and limits, not only favorable results."},{"id":"a025-v7-24-k2","title":"驗證與判讀","titleEn":"Verification and interpretation","text":"教育模型可訓練判讀，但不取代製程資格認證。","textEn":"Educational models train interpretation but do not replace process qualification."}],"quiz":{"question":"哪種交付最能支持下一步決策？","questionEn":"Which deliverable best supports the next decision?","options":["只列最高改善百分比。","把所有待驗證項改成通過。","包含假設、失敗與未知項的證據包。"],"optionsEn":["Only the largest improvement percentage.","Mark every unverified item passed.","Evidence including assumptions, failures and unknowns."],"answer":2,"explanation":"包含假設、失敗與未知項的證據包。 設計審查評估證據與限制，不只展示最漂亮的結果。","explanationEn":"Evidence including assumptions, failures and unknowns. Design review evaluates evidence and limits, not only favorable results."}}]}],"curriculumVersion":7,"subcategory":"devices","subcategoryTitle":"先進電晶體","subcategoryTitleEn":"Advanced transistors"}};
